__global__ void deliver_compound_sc(int nsite,int step,float dt,float rate_hz,float theta_hz,bool theta,float scale,const uint64_t*target,const uint32_t*contacts,const uint8_t*cls,uint32_t*rng,float apn,float npn,float ain,float nin,float*scar_pc,float*scad_pc,float*scnr_pc,float*scnd_pc,float*scar_int,float*scad_int,float*scnr_int,float*scnd_int,unsigned long long*arrivals,unsigned long long*vesicles){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=nsite)return;uint32_t s=rng[i];float modulation=theta?fmaxf(0.f,1.f+sinf(6.28318530718f*theta_hz*(step*dt*.001f))):1.f;float mu=contacts[i]*rate_hz*modulation*dt*.001f;int spikes=poisson_small(mu,s);if(!spikes){rng[i]=s;return;}uint8_t c=cls[i];int nrrp=c==0?12:(c==1?2:8);float use=c==0?.14f:.11f,total_fraction=0;int total_nr=0;for(int q=0;q<spikes;q++){int nr=0;for(int k=0;k<nrrp;k++){float u=(rand32(s)+1.f)*2.3283064e-10f;nr+=u<use;}total_nr+=nr;total_fraction+=float(nr)/nrrp;}rng[i]=s;atomicAdd(arrivals,(unsigned long long)spikes);atomicAdd(vesicles,(unsigned long long)total_nr);if(total_nr==0)return;uint64_t z=target[i];float g=(c==0?.85f:(c==1?15.f:1.5f))*total_fraction*scale,ratio=c==0?1.23f:.16f;if(c==0){atomicAdd(&scar_pc[z],g*apn);atomicAdd(&scad_pc[z],g*apn);atomicAdd(&scnr_pc[z],g*ratio*npn);atomicAdd(&scnd_pc[z],g*ratio*npn);}else{atomicAdd(&scar_int[z],g*ain);atomicAdd(&scad_int[z],g*ain);atomicAdd(&scnr_int[z],g*ratio*nin);atomicAdd(&scnd_int[z],g*ratio*nin);}}
