__global__ void deliver_edges(int ne,int n,int step,int ringmask,float dt,const int32_t*pre,const uint16_t*delay,const uint8_t*model,const float*gpeak,const float*use,const float*dep,const float*fac,const uint8_t*nrrp,const float*nmda_ratio,const uint8_t*nmda_slow,const uint64_t*prefix,const uint64_t*postcomp,const uint8_t*history,float scale,float anorm,float gnorm,float nfnorm,float nsnorm,bool stochastic,float*stpu,float*stpr,int32_t*last,uint32_t*edge_rng,float*ar,float*ad,float*gr,float*gd,float*nfr,float*nfd,float*nsr,float*nsd,unsigned long long*delivered,unsigned long long*release_trials,unsigned long long*release_failures,unsigned long long*released_vesicles){int e=blockIdx.x*blockDim.x+threadIdx.x;if(e>=ne)return;int d=delay[e];if(step<d||!history[((step-d)&ringmask)*n+pre[e]])return;float u=stpu[e],r=stpr[e];if(last[e]>=0){float delta=(step-last[e])*dt;u=use[e]+(u-use[e])*expf(-delta/fac[e]);r=1.f-(1.f-r)*expf(-delta/dep[e]);}float probability=fminf(1.f,fmaxf(0.f,u*r)),released=probability;if(stochastic){uint32_t s=edge_rng[e];int nr=0;for(int k=0;k<nrrp[e];k++){float q=(rand32(s)+1.f)*2.3283064e-10f;nr+=q<probability;}edge_rng[e]=s;released=float(nr)/float(nrrp[e]);atomicAdd(release_trials,1ULL);atomicAdd(released_vesicles,(unsigned long long)nr);if(nr==0)atomicAdd(release_failures,1ULL);}r*=1.f-u;u+=use[e]*(1.f-u);stpu[e]=u;stpr[e]=r;last[e]=step;uint64_t multiplicity=prefix[e+1]-prefix[e];atomicAdd(delivered,(unsigned long long)multiplicity);float w=scale*gpeak[e]*released*(model[e]?gnorm:anorm),wn=scale*gpeak[e]*nmda_ratio[e]*released*(nmda_slow[e]?nsnorm:nfnorm);for(uint64_t s=prefix[e];s<prefix[e+1];s++){uint64_t z=postcomp[s];if(model[e]){atomicAdd(&gr[z],w);atomicAdd(&gd[z],w);}else{atomicAdd(&ar[z],w);atomicAdd(&ad[z],w);if(nmda_slow[e]){atomicAdd(&nsr[z],wn);atomicAdd(&nsd[z],wn);}else{atomicAdd(&nfr[z],wn);atomicAdd(&nfd[z],wn);}}}}
__global__ void build_membrane(uint64_t total,float dt,const float*area,const Param*p,float*V,Gate*Q,const float*ar,const float*ad,const float*gr,const float*gd,const float*nfr,const float*nfd,const float*nsr,const float*nsd,const float*scar_pc,const float*scad_pc,const float*scnr_pc,const float*scnd_pc,const float*scar_int,const float*scad_int,const float*scnr_int,const float*scnd_int,float*D,float*B,float*off,float*old){uint64_t z=uint64_t(blockIdx.x)*blockDim.x+threadIdx.x;if(z>=total)return;gate_step(Q[z],V[z],dt,false);old[z]=V[z];float eps=1e-3f,I=current(p[z],Q[z],V[z]),g=(current(p[z],Q[z],V[z]+eps)-current(p[z],Q[z],V[z]-eps))/(2*eps),G=g*area[z]*.01f,src=(g*V[z]-I)*area[z]*.01f,cap=p[z].cm*area[z]*1e-5f;float ga=fmaxf(0.f,ad[z]-ar[z])+fmaxf(0.f,scad_pc[z]-scar_pc[z])+fmaxf(0.f,scad_int[z]-scar_int[z]),gg=fmaxf(0.f,gd[z]-gr[z]),gn=fmaxf(0.f,nfd[z]-nfr[z])+fmaxf(0.f,nsd[z]-nsr[z])+fmaxf(0.f,scnd_pc[z]-scnr_pc[z])+fmaxf(0.f,scnd_int[z]-scnr_int[z]),mg=1.f/(1.f+expf(-.062f*V[z])/2.62f),Gs=.001f*(ga+gg+gn*mg);D[z]=cap/dt+.5f*(G+Gs);B[z]=(cap/dt-.5f*(G+Gs))*V[z]+src+.001f*(gg*(-75.f));off[z]=0;}
